Translate("deDE", "city-of-dalaran", {
	title = "Stadt Dalaran",
	aliases = { "Dalaran-Stadt", "die Stadt der Magier" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Stadt Dalaran steht wieder am Westufer des {red:lordamere-lake}Lordameresees{/red}, am Fuß des {link:alterac-mountains}Alteracgebirges{/link}. Ihre violetten Türme erheben sich über neuen Mauern und hellen Straßen, ihre Banken und Gasthäuser sind geöffnet, und ihre Magier wandeln wieder unter Händlern, Handwerkern und Gästen aus fernen Landen. Jahrelang verbarg sich die Stadt hinter einer großen Kuppel aus Licht, während ihre Zauberer sie wiederaufbauten. Diese Barriere ist gefallen. Die Welt kann {link:dalaran}Dalaran{/link} wieder sehen, und Dalaran muss sich nun der Welt stellen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Geschichte von {link:dalaran}Dalaran{/link}, der ersten der freien Städte von {link:arathor}Arathor{/link} und Heimat der {link:kirin-tor}Kirin Tor{/link}, wird in ihrer eigenen Chronik erzählt. Im {link:third-war}Dritten Krieg{/link} kam die {link:scourge}Geißel{/link} vor ihre Tore und nahm das Zauberbuch von {link:medivh}Medivh{/link}, und {link:archimonde}Archimonde{/link} zerbrach die Stadt mit einem einzigen Zauber. Die überlebenden Magier kehrten in die Ruinen zurück. Sie errichteten eine gewaltige magische Kuppel über dem Herzen ihrer Stadt, und dahinter machten sie sich an die Arbeit. Draußen bewachten die Patrouillen der Zauberer Dalarans und ihre gebundenen Elementare die zerstörten Außenbezirke, und wenige, die sich näherten, waren willkommen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Arbeit ist getan, oder beinahe. Niemand außerhalb der {link:kirin-tor}Kirin Tor{/link} kann bisher sagen, warum die Barriere fiel. Die Stadt ist offen, aber nicht in Frieden. Verzauberungen gehen fehl, arkane Konstrukte reißen sich los, und dämonische Energie ist in ihren Straßen gespürt worden. Ermittler der Kirin Tor sprechen mit gedämpfter Stimme von einer Störung, die mit jedem Tag schlimmer wird, und sie haben Befehl, die Bürger ruhig zu halten. Die Kirin Tor zählen sich nun zu den Nationen der {link:alliance}Allianz{/link}. Die {link:horde}Horde{/link} ist hier nicht willkommen, und die Wachen der Stadt behandeln ihr Volk als Feinde. Stattdessen sind neue Freunde gekommen: der {link:high-order}High Order{/link} der {link:skyborne}Skyborne{/link}, dessen Skycutter-Schiffe zwischen {link:dalaran}Dalaran{/link} und {link:zephras-isle}Zephras Isle{/link} über die Ebenen hinweg segeln.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:kirin-tor}Kirin Tor{/link}.{/b} Erzmagier, Archivare, Arkanisten und Ermittler, die Herren der Stadt.
• {b}Die Wachen von {link:dalaran}Dalaran{/link}.{/b} Wachen und Vollstrecker der Kirin Tor sowie arkane {link:the-night-watch}Wächter{/link}, die von selbst Wache halten.
• {b}Bürger und Händler.{/b} Bankiers, Wirte, Schmiede, Schneider, Juweliere und ein Spielzeugmacher, dazu ein Waisenhaus mit seiner Hausmutter.
• {b}Die {link:skyborne}Skyborne{/link}.{/b} Magier des {link:high-order}High Order{/link}, die am Skycutter-Anleger der Stadt ankommen.
• {b}Besucher.{/b} Unter ihnen ein Lehrer der Druiden und ein Hochgeborener, der von weit her gekommen ist.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Gründung.{/b} {link:dalaran}Dalaran{/link} war die erste Stadt Arathors, die sich selbst regierte, und seine Magier gründeten die {link:kirin-tor}Kirin Tor{/link}.
• {b}Der Fall.{/b} Im Dritten Krieg wurde die Stadt zerstört.
• {b}Die Barriere.{/b} Die Magier bauten Dalaran hinter einer Kuppel wieder auf, die die Welt aussperrte.
• {b}Die Gegenwart.{/b} Die Barriere ist fort, und die Stadt hat ihre Tore ihren Verbündeten geöffnet.]=],
		},
		{
			title = "Überlieferungen der Stadt",
			text = [=[• Zauberer aus {link:dalaran}Dalaran{/link} beobachten nun die Straßen des Nordens. Im {link:silverpine-forest}Silberwald{/link} sagt man, sie täten dies, seit die Barriere fiel.
• Der {link:archmage-ansirem-runeweaver}Erzmagier Ansirem Runeweaver{/link} schrieb einst ein Buch über die Legenden der Gurubashitrolle. Seine Tochter wurde zu seinem Kummer Piratin.
• Die {link:kirin-tor}Kirin Tor{/link} unterhalten ein Portal für den {link:high-order}High Order{/link}, damit seine jungen Magier {link:stormwind-city}Stormwind{/link} erreichen und dort den Regenten treffen können.]=],
		},
	},
})

Translate("deDE", "the-eventide", {
	title = "The Eventide",
	aliases = { "Eventide" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[The Eventide ist eines der Viertel der wiederaufgebauten {link:city-of-dalaran}Stadt Dalaran{/link}. Wie der Rest der Stadt wurde es hinter der großen Barriere neu errichtet, während die Welt draußen es nicht sehen konnte, und es ist erst kürzlich für Besucher geöffnet worden. Seine Straßen sind neu, und viele der Leute, die darauf gehen, ebenso. Keine Chronik verzeichnet bisher, wer in The Eventide wohnt oder was die Magier dort zuerst bauten. Wer durch seine Straßen geht, findet eine Stadt, die stolz auf ihre Wiederherstellung ist und unruhiger, als sie zugeben möchte.]=],
		},
	},
})

Translate("deDE", "archmage-ansirem-runeweaver", {
	title = "Erzmagier Ansirem Runeweaver",
	subtitle = "Erzmagier der Kirin Tor",
	found = "Die Stadt Dalaran",
	hint = [=[Sucht den Erzmagier der Kirin Tor, dessen Wissen vom Schlingendorntal bis zu den Himmeln reicht.]=],
	allegiance = "Kirin Tor",
	aliases = { "Ansirem Runeweaver", "Ansirem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzmagier Ansirem Runeweaver ist einer der großen Magier der {link:kirin-tor}Kirin Tor{/link}. Er hat den langen Wiederaufbau von {link:dalaran}Dalaran{/link} hindurch gearbeitet, und seine Gelehrsamkeit ist gewaltig. Vor Jahren schrieb er ein Buch über die Legenden des Gurubashireichs, und er weiß mehr über die Trollrelikte des Schlingendorntals als jeder Gelehrte im Norden. Er ist auch Vater, und seine einzige Tochter hat ihm auf höchst ungewöhnliche Weise das Herz gebrochen: Sie lief nach {link:booty-bay}Booty Bay{/link} davon, um Piratin zu werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ansirem ist das Gesicht der {link:kirin-tor}Kirin Tor{/link} für die Welt jenseits ihrer Mauern. Er beantwortet die Fragen von Prinzen und Piraten gleichermaßen. Als die {link:skyborne}Skyborne{/link} von {link:zephras-isle}Zephras Isle{/link} vom Kult des Windlords bedroht wurden, war es Ansirem, der mit den Magiern der Kirin Tor kam, um ihnen beizustehen. Ihre Freundschaft ist nun das Bündnis seines Ordens.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht den Fluch des Steins der Gezeiten für die Goblins von {link:booty-bay}Booty Bay{/link}.
• Er fand im {link:stranglethorn-vale}Schlingendorntal{/link} einen Trolldolch und gab ihn seiner eigensinnigen Tochter {link:catelyn-the-blade}Catelyn{/link}.
• Er kam mit den {link:kirin-tor}Kirin Tor{/link} nach {link:zephras-isle}Zephras Isle{/link} und traf den Obersten Magister des {link:high-order}High Order{/link}.
• Er schickt junge Druiden der {link:skyborne}Skyborne{/link} zum {link:cenarion-circle}Zirkel des Cenarius{/link}, damit sie lernen, ihre Heimat zu retten.]=],
		},
	},
	chapters = {
		{
			title = "Der Stein der Gezeiten",
			hint = [=[Bringt dem Erzmagier ein magisches Rätsel aus dem Schlingendorntal.]=],
			text = [=[Die Armschienen stammten von Wasserelementaren im fernen Süden, und sie trugen die Rückstände eines Trollfluchs. Ansirem war begeistert. Er hatte vor langer Zeit über den Stein der Gezeiten geschrieben. Der Magier, der den Stein besaß, so fand er heraus, verstärkte dessen Macht durch einen Altar. Man konnte sie mit dem richtigen Relikt überwinden, und er wusste genau, mit welchem: einem uralten Trolldolch. Es gab nur ein Problem. Er hatte ihn seiner Tochter geschenkt.]=],
		},
		{
			title = "Die Kinder der Natur",
			hint = "Sprecht als junger Druide der Himmel mit dem Erzmagier.",
			text = [=[Den jungen Druiden der {link:skyborne}Skyborne{/link} bietet Ansirem einen Rat, den sie von einem Magier nicht erwartet hätten. Es gebe einen uralten Orden von Naturkundigen auf {link:azeroth}Azeroth{/link}, sagt er ihnen, und eine Nachtelfe in {link:stormwind-city}Stormwind{/link} könne ihnen den Weg zu seiner Feste in {link:moonglade}Moonglade{/link} zeigen. Wenn sie ihre Heimat retten wollten, hätten sie viel zu lernen.]=],
		},
	},
	mentions = {
		{ text = "Magische Analyse" },
		{ text = "Ansirems Schlüssel" },
		{ text = "Kind der Natur" },
		{
			text = [=[Stellt {link:high-priestess-lorthuna}Lorthuna{/link}, auf den Türmen von {link:zephras-isle}Zephras{/link}]=],
		},
	},
	bonds = {
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "traf ihn auf den Türmen" },
		{ id = "archmage-modera", name = "Erzmagierin Modera", note = "eine Mit-Erzmagierin" },
		{ id = "denaaris-stargale", name = "Denaaris Stargale", note = "empfängt den High Order in seiner Stadt" },
	},
})

Translate("deDE", "archmage-modera", {
	title = "Erzmagierin Modera",
	subtitle = "Erzmagierin der Kirin Tor",
	found = "Die Stadt Dalaran",
	hint = [=[Sucht die alte Erzmagierin, die den Kirin Tor seit dem Zweiten Krieg dient.]=],
	allegiance = "Kirin Tor",
	aliases = { "Modera" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzmagierin Modera ist eines der ältesten Mitglieder des herrschenden Rates der {link:kirin-tor}Kirin Tor{/link}. Sie saß unter den Magiern, die {link:dalaran}Dalaran{/link} in den Tagen des {link:second-war}Zweiten Krieges{/link} regierten. Vor der Seuche sprach sie sich gegen {link:kel-thuzad}Kel'Thuzad{/link} aus, als seine Studien der Nekromantie ans Licht kamen, und warnte, dass seine Methoden sie alle der Verdammnis preisgeben würden. Ihre Warnung wurde beherzigt, und er wurde verstoßen. Sie überlebte den Fall der Stadt und blieb, um sie wieder auferstehen zu sehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Modera ist eine lebende Erinnerung an die alten {link:kirin-tor}Kirin Tor{/link} und eine Stimme, die über den Mann recht behielt, der {link:lordaeron}Lordaeron{/link} zerstörte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Bisher ist kein Wort über ihren Anteil am Wiederaufbau verzeichnet oder darüber, was sie von der gefallenen Barriere hält.]=],
		},
	},
	bonds = {
		{ id = "archmage-ansirem-runeweaver", name = "Erzmagier Ansirem Runeweaver", note = "ein Mit-Erzmagier" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "sie sprach sich gegen ihn aus" },
	},
})

