	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ermittlerin Kath'leen untersucht eine Unruhe, die die Magier Dalarans lieber für sich behalten würden. Eine Störung ist in der Stadt gespürt worden, und sie hat nur an Schwere zugenommen. Sie sorgt sich, was geschehen wird, wenn die Bürger nichts davon erfahren. Ihre Partnerin, {link:investigator-silva}Ermittlerin Silva{/link}, erinnert sie an ihre Befehle.]=],
