Translate("deDE", "investigator-silva", {
	title = "Ermittlerin Silva",
	subtitle = "Ermittlerin der Kirin Tor",
	found = "Ein stiller Winkel von Dalaran, bei Ermittlerin Kath'leen",
	hint = [=[Horcht auf die beiden Ermittlerinnen, die in den Straßen von Dalaran mit gedämpfter Stimme sprechen.]=],
	allegiance = "Kirin Tor",
	aliases = { "Silva" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ermittlerin Silva arbeitet an der Seite von {link:investigator-kath-leen}Ermittlerin Kath'leen{/link} an einer Sache, die die {link:kirin-tor}Kirin Tor{/link} beunruhigt. Die beiden haben Befunde untersucht, die von einem Pylon stammen, und Silva will sie noch einmal durchgehen, für den Fall, dass sie etwas übersehen haben. Silva hält sich an die Befehle, die sie erhielten. Bis sie es sicher wissen, ist Schweigen der beste Weg, die Stadt ruhig zu halten.]=],
