		},
		{
			title = "Nicht überliefert",
			text = [=[Noch sagt keine Aufzeichnung, welchen Pylon sie untersuchten oder was sie fanden.]=],
		},
	},
	bonds = {
		{ id = "investigator-kath-leen", name = "Ermittlerin Kath'leen", note = "ihre Partnerin" },
	},
})
